<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;
use App\Http\Requests\Admin\CategoryRequest;
use App\Models\Category;
use App\Services\MediaService;
class CategoryController extends Controller {public function __construct(private MediaService $media){}public function index(){return view('admin.categories.index',['categories'=>Category::with('parent')->ordered()->paginate(30)]);}public function create(){return view('admin.categories.form',['category'=>new Category,'parents'=>Category::whereNull('parent_id')->ordered()->get()]);}public function store(CategoryRequest $r){$c=$this->save(new Category,$r);return redirect()->route('admin.categories.edit',$c)->with('success','Category created.');}public function edit(Category $category){return view('admin.categories.form',['category'=>$category,'parents'=>Category::whereNull('parent_id')->where('id','!=',$category->id)->ordered()->get()]);}public function update(CategoryRequest $r,Category $category){$this->save($category,$r);return back()->with('success','Category updated.');}public function destroy(Category $category){abort_if($category->products()->exists()||$category->children()->exists(),422,'Move products and child categories before deleting.');$category->delete();return back()->with('success','Category deleted.');}private function save(Category $c,CategoryRequest $r){$d=$r->validated();foreach(['image','banner_image'] as $f)if($r->hasFile($f)){$this->media->delete($c->{$f});$d[$f]=$this->media->store($r->file($f),'categories');}$d['is_active']=$r->boolean('is_active');$d['show_in_menu']=$r->boolean('show_in_menu');$c->fill($d)->save();return $c;}}
